package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	dataDir  string
}

type Session struct {
	UserID    string
	Token     string
	CreatedAt time.Time
	DataPath  string
}

func generateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := io.ReadFull(rand.Reader, b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func NewSessionStore(dataDir string) *SessionStore {
	os.MkdirAll(dataDir, 0700)
	return &SessionStore{
		sessions: make(map[string]*Session),
		dataDir:  dataDir,
	}
}

func (s *SessionStore) CreateSession(userID string) (*Session, error) {
	token, err := generateToken()
	if err != nil {
		return nil, err
	}

	userDir := filepath.Join(s.dataDir, userID)
	os.MkdirAll(userDir, 0700)

	sess := &Session{
		UserID:    userID,
		Token:     token,
		CreatedAt: time.Now(),
		DataPath:  userDir,
	}

	s.mu.Lock()
	s.sessions[token] = sess
	s.mu.Unlock()

	return sess, nil
}

func (s *SessionStore) GetSession(token string) (*Session, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	sess, ok := s.sessions[token]
	return sess, ok
}

// sanitizeFilename ensures no path traversal in user-provided filenames
func sanitizeFilename(name string) string {
	// Remove any directory components
	name = filepath.Base(name)
	// Remove leading dots to prevent hidden files
	name = strings.TrimLeft(name, ".")
	if name == "" {
		name = "unnamed"
	}
	return name
}

// verifyPathOwnership checks that the resolved path belongs to the user's directory
func verifyPathOwnership(path string, userDir string) bool {
	absPath, err := filepath.Abs(path)
	if err != nil {
		return false
	}
	absUserDir, err := filepath.Abs(userDir)
	if err != nil {
		return false
	}
	// Resolve symlinks for the check
	resolvedPath, err := filepath.EvalSymlinks(absPath)
	if err != nil {
		// File might not exist yet for writes
		resolvedPath = absPath
	}
	resolvedDir, err := filepath.EvalSymlinks(absUserDir)
	if err != nil {
		resolvedDir = absUserDir
	}
	return strings.HasPrefix(resolvedPath, resolvedDir+string(os.PathSeparator)) ||
		resolvedPath == resolvedDir
}

func (s *SessionStore) HandleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetPath := filepath.Join(sess.DataPath, filename)

	// Verify the target path is within the user's directory
	if !verifyPathOwnership(targetPath, sess.DataPath) {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	body := http.MaxBytesReader(w, r.Body, 5*1024*1024)
	data, err := io.ReadAll(body)
	if err != nil {
		http.Error(w, "Read error", http.StatusBadRequest)
		return
	}

	if err := os.WriteFile(targetPath, data, 0600); err != nil {
		http.Error(w, "Write error", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	fmt.Fprintf(w, "{\"status\":\"uploaded\",\"file\":\"%s\"}", filename)
}

func (s *SessionStore) HandleDownload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetPath := filepath.Join(sess.DataPath, filename)

	// Security check: verify path ownership before reading
	if !verifyPathOwnership(targetPath, sess.DataPath) {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// TOCTOU gap: between verifyPathOwnership and os.ReadFile,
	// the file or a directory component could be replaced with a symlink
	data, err := os.ReadFile(targetPath)
	if err != nil {
		http.Error(w, "File not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=\"%s\"", filename))
	w.Write(data)
}

func (s *SessionStore) HandleShare(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	token := r.Header.Get("X-Session-Token")
	sess, ok := s.GetSession(token)
	if !ok {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	filename := sanitizeFilename(r.URL.Query().Get("name"))
	targetUser := r.URL.Query().Get("target_user")

	// Validate target_user is alphanumeric
	for _, c := range targetUser {
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			http.Error(w, "Invalid target user", http.StatusBadRequest)
			return
		}
	}

	sourcePath := filepath.Join(sess.DataPath, filename)

	// Verify source exists and belongs to user
	if !verifyPathOwnership(sourcePath, sess.DataPath) {
		http.Error(w, "Access denied", http.StatusForbidden)
		return
	}

	// Create symlink in target user's directory for sharing
	targetDir := filepath.Join(s.dataDir, targetUser)
	os.MkdirAll(targetDir, 0700)
	linkPath := filepath.Join(targetDir, "shared_"+filename)

	// Remove existing link if any
	os.Remove(linkPath)

	// Create symlink pointing to the source file
	if err := os.Symlink(sourcePath, linkPath); err != nil {
		http.Error(w, "Share failed", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "{\"status\":\"shared\",\"link\":\"shared_%s\"}", filename)
}

func main() {
	store := NewSessionStore("/var/app/data")

	mux := http.NewServeMux()
	mux.HandleFunc("/upload", store.HandleUpload)
	mux.HandleFunc("/download", store.HandleDownload)
	mux.HandleFunc("/share", store.HandleShare)

	server := &http.Server{
		Addr:              ":8443",
		Handler:           mux,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		ReadHeaderTimeout: 5 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 16,
	}

	fmt.Println("Server starting on :8443")
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "Server error: %v\n", err)
		os.Exit(1)
	}
}
